46	    /** The owner's salutation: '&lt;title&gt; &lt;lastName&gt;' when a title was supplied,
47	     * otherwise just the last name. */
48	    default String salutation(Owner owner) {
49	        String title = owner.getTitle();
50	        return (title == null || title.isBlank()) ? owner.getLastName() : title + " " + owner.getLastName();
51	    }
52	
53	    /** Format an owner's name as 'LastName, FirstName' for display. */
54	    default String displayName(Owner owner) {
55	        return owner.getLastName() + ", " + owner.getFirstName();
56	    }
57	
58	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
59	    default String initials(Owner owner) {
60	        return initial(owner.getFirstName()) + initial(owner.getLastName());
61	    }
62	
63	    /** The stored E.164 telephone formatted for humans (see {@link OwnerTelephones#toDisplay}). */
64	    default String telephoneDisplay(Owner owner) {
65	        return OwnerTelephones.toDisplay(owner.getTelephone());
66	    }
67	
68	    private static String initial(String name) {
69	        return Character.toUpperCase(name.charAt(0)) + ".";
70	    }
71	
72	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
73	     * last two digits of the registrationDate year. */
74	    default String membershipNumber(Owner owner) {
75	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
76	            return null;
77	        }
78	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
79	    }
80	
81	    /** The owner's membership points: starts at 0, plus 2 when an email is present, plus 1 when
82	     * namesakeCount is 0, plus 2 for a household of 3 or more, plus 3 when tenure exceeds 365 days. */
83	    default int membershipPoints(Owner owner) {
84	        int points = 0;
85	        if (hasEmail(owner)) {
86	            points += 2;
87	        }
88	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
89	            points += 1;
90	        }
91	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
92	            points += 2;
93	        }
94	        if (Tenure.days(owner.getRegistrationDate()) > 365) {
95	            points += 3;
96	        }
97	        return points;
98	    }
99	
100	    /** The owner's membership level from 1 to 4, derived from {@link #membershipPoints(Owner)}:
101	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
102	    default int membershipLevel(Owner owner) {
103	        int points = membershipPoints(owner);
104	        if (points <= 1) {
105	            return 1;
106	        }
107	        if (points <= 3) {
108	            return 2;
109	        }
110	        if (points <= 5) {
111	            return 3;
112	        }
113	        return 4;
114	    }
115	
116	    /** The owner's canonical region: the REGION segment of the customer code (see
117	     * {@link CustomerCode}), or null when the customer code is unset. */
118	    default String locality(Owner owner) {
