143	
144	    /** The Luhn check digit over the digits of the owner's customer code, or null when unset. */
145	    default Integer checkDigit(Owner owner) {
146	        return owner.getCustomerCode() == null ? null : CheckDigit.luhn(owner.getCustomerCode());
147	    }
148	
149	    /** The owner's age band on their registration date, derived from their birth date (see
150	     * {@link AgeBand}), or null when either date is unset. */
151	    default String ageBand(Owner owner) {
152	        return AgeBand.on(owner.getBirthDate(), owner.getRegistrationDate());
153	    }
154	
155	    /** Whether the owner soft-matched an existing owner at creation, i.e. it has a
156	     * {@code possibleDuplicateOf} id. */
157	    default boolean possibleDuplicate(Owner owner) {
158	        return owner.getPossibleDuplicateOf() != null;
159	    }
