1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Resolves the effective registration date for a new owner — the date supplied in the request, or
11	 * the server's current date when the request omitted one — and rolls a weekend onto the next
12	 * business day via {@link BusinessDays}. Runs before {@link RejectDailyOwnerLimit} so the daily
13	 * cap counts against this same business day, and publishes the date once so
14	 * {@link ApplyOwnerRegistrationDate} stamps the owner with exactly the value that was counted.
15	 */
16	public class ResolveOwnerRegistrationDate {
17	
18	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
19	        LocalDate effective = request.getRegistrationDate() != null
20	                ? request.getRegistrationDate() : LocalDate.now();
21	        registrationDate.set(BusinessDays.rollForward(effective));
22	    }
23	}
