1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
8	
9	/**
10	 * Rejects a create-owner request once {@link #DAILY_LIMIT} or more owners have already been
11	 * registered on the new owner's business day, responding 429. Counts against the effective
12	 * registration date resolved by {@link ResolveOwnerRegistrationDate} — the supplied-or-defaulted
13	 * date already rolled onto a business day — so the count and the new owner share one day.
14	 */
15	public class RejectDailyOwnerLimit {
16	
17	    /** Maximum number of owners that may be registered in a single day. */
18	    static final int DAILY_LIMIT = 100;
19	
20	    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
21	            throws DailyOwnerLimitException {
22	        if (OwnerRegistrationDays.size(ownerRepository.findAll(), registrationDate) >= DAILY_LIMIT) {
23	            throw new DailyOwnerLimitException(DAILY_LIMIT);
24	        }
25	    }
26	}
