6	/**
7	 * The single definition of an owner's <em>age band</em> on their registration date, derived from
8	 * their birth date: {@code MINOR} (under 18), {@code ADULT} (18 to 64) or {@code SENIOR} (65 or
9	 * over). The age is the number of whole years between the two dates.
10	 *
11	 * <p>Returned by the response mapper alongside the owner's other derived fields; absent (null)
12	 * when either date is missing, since without a birth date there is no band to report.
13	 */
14	public final class AgeBand {
15	
16	    private AgeBand() {
17	    }
18	
19	    /** The age band on {@code registrationDate} for an owner born on {@code birthDate}, or null
20	     * when either date is unknown. */
21	    public static String on(LocalDate birthDate, LocalDate registrationDate) {
22	        if (birthDate == null || registrationDate == null) {
23	            return null;
24	        }
25	        int years = Period.between(birthDate, registrationDate).getYears();
26	        if (years < 18) {
27	            return "MINOR";
28	        }
29	        if (years < 65) {
30	            return "ADULT";
31	        }
32	        return "SENIOR";
33	    }
34	}
